&lt;h1 style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;color: rgb(126, 140, 141); font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;&lt;strong&gt;Human Data Operations Partner, Research&lt;/strong&gt;&lt;/span&gt;&lt;/h1&gt;
