&lt;h1 style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-family: tahoma, arial, helvetica, sans-serif; color: rgb(126, 140, 141);&quot;&gt;&lt;strong&gt;Human Data Quality Engineer (Founding Team)&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/h1&gt;
